function resetGame(seed) {
  rng = mulberry32(seed);
  score = 0;
  lives = 1;
  gameState = 'PLAYING';
  platforms = [];

  // Generate Procedural Vertical Level
  let currentY = 350; // Floor is at 400
  let platW = 120;
  let platX = (width - 8) / 2 - platW / 2;
  platforms.push({x: platX, y: currentY, w: platW, h: 20, type: 'normal'});

  while (currentY > -3000) {
    // Gap vertically
    currentY -= rng() * 50 + 40; 

    // Width and position logic ensuring overlap capability
    let pW = rng() * 60 + 40;
    let prevCenterX = platX + platW / 2;

    // Keep next platform reachable horizontally
    let minX = Math.max(0, prevCenterX - 120);
    let maxX = Math.min(width - 8 - pW, prevCenterX + 120 - pW);
    if (maxX < minX) maxX = minX;

    platX = minX + rng() * (maxX - minX);
    platW = pW;

    // 20% chance for a tall block that acts as a wall
    let pH = rng() < 0.2 ? rng() * 40 + 20 : 15;
    platforms.push({x: platX, y: currentY, w: platW, h: pH, type: 'normal'});

    // Occasional edge walls to aid/obstruct bouncing
    if (rng() < 0.2) {
      if (rng() < 0.5) {
        platforms.push({x: 0, y: currentY - 50, w: 20, h: 80, type: 'normal'});
      } else {
        platforms.push({x: width - 8 - 20, y: currentY - 50, w: 20, h: 80, type: 'normal'});
      }
    }
  }

  // Goal platform at the very top
  currentY -= 100;
  platforms.push({x: 0, y: currentY, w: width - 8, h: 20, type: 'goal'});

  // Initialize Player
  player = {
    x: (width - 8) / 2 - 8,
    y: 350 - 16,
    w: 16, h: 16,
    vx: 0, vy: 0,
    state: 0, // 0: Idle, 1: Charging, 2: Air
    charge: 0,
    jumpDir: 0
  };

  cameraY = 0;
  maxReachedY = player.y;
}
